<?php
require 'config.php'; require 'functions.php'; require_officer();
$id = filter_input(INPUT_GET, 'id', FILTER_VALIDATE_INT, ['options' => ['min_range' => 1]]);
$page = filter_input(INPUT_GET, 'page', FILTER_VALIDATE_INT, ['options' => ['min_range' => 1]]) ?: 1;
$revisionId = filter_input(INPUT_GET, 'revision', FILTER_VALIDATE_INT, ['options' => ['min_range' => 1]]) ?: null;
if (!$id) { http_response_code(400); exit('Invalid announcement.'); }
$announcementQuery = $pdo->prepare('SELECT id,title,version FROM announcements WHERE id=?');
$announcementQuery->execute([$id]);
$announcement = $announcementQuery->fetch();
if (!$announcement) { http_response_code(404); exit('Announcement not found.'); }
$selectedRevision = null;
if ($revisionId) {
    $selectedQuery = $pdo->prepare('SELECT r.*,u.name editor,s.revision_number restored_from_version FROM announcement_revisions r LEFT JOIN users u ON u.id=r.editor_id LEFT JOIN announcement_revisions s ON s.id=r.restore_from_revision_id WHERE r.id=? AND r.announcement_id=?');
    $selectedQuery->execute([$revisionId, $id]);
    $selectedRevision = $selectedQuery->fetch();
    if (!$selectedRevision) { http_response_code(404); exit('Revision not found.'); }
}
$perPage = 50;
$countQuery = $pdo->prepare('SELECT COUNT(*) FROM announcement_revisions WHERE announcement_id=?');
$countQuery->execute([$id]);
$total = (int)$countQuery->fetchColumn();
$pages = max(1, (int)ceil($total / $perPage));
$page = min($page, $pages);
$offset = ($page - 1) * $perPage;
$historyQuery = $pdo->prepare('SELECT r.id,r.revision_number,r.title,r.category,r.status,r.created_at,u.name editor,s.revision_number restored_from_version FROM announcement_revisions r LEFT JOIN users u ON u.id=r.editor_id LEFT JOIN announcement_revisions s ON s.id=r.restore_from_revision_id WHERE r.announcement_id=? ORDER BY r.revision_number DESC LIMIT ? OFFSET ?');
$historyQuery->bindValue(1, $id, PDO::PARAM_INT);
$historyQuery->bindValue(2, $perPage, PDO::PARAM_INT);
$historyQuery->bindValue(3, $offset, PDO::PARAM_INT);
$historyQuery->execute();
$revisions = $historyQuery->fetchAll();
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Announcement History · CS3B</title><link rel="icon" href="assets/brand/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="assets/style.css"><script src="assets/theme.js" defer></script></head><body><header class="top"><div class="site-brand-wrap"><a href="./" class="site-brand" aria-label="Pilimon Bulletin home"><img class="site-brand__logo" src="assets/brand/pilimon-bulletin-wordmark-light.svg" alt="Pilimon Bulletin"><span class="site-brand__meta">Staff view</span></a></div><nav><a href="dashboard">Dashboard</a><a href="announcement-form?id=<?=$id?>">Edit announcement</a><a href="logout">Logout</a></nav></header><main class="container narrow"><div class="dashhead"><div><p class="eyebrow">Version history</p><h1><?=e($announcement['title'])?></h1></div><a href="dashboard">Back to dashboard</a></div>
<?php if($selectedRevision): ?><article class="card revision-detail"><div class="meta"><span>Version <?=e($selectedRevision['revision_number'])?></span><time><?=e(format_campus_datetime($selectedRevision['created_at'],'M j, Y · g:i A'))?></time></div><h2><?=e($selectedRevision['title'])?></h2><p><?=e($selectedRevision['category'])?> · <?=e($selectedRevision['status'])?> · Edited by <?=e($selectedRevision['editor']??'Former account')?></p><?php if($selectedRevision['restored_from_version']): ?><p class="alert success">Restored from version <?=e($selectedRevision['restored_from_version'])?>.</p><?php endif; ?><dl class="revision-metadata"><dt>Publication</dt><dd><?=e($selectedRevision['status']==='scheduled' ? 'Scheduled for '.format_campus_datetime($selectedRevision['publish_at'],'M j, Y · g:i A') : ($selectedRevision['published_at'] ? 'Published '.format_campus_datetime($selectedRevision['published_at'],'M j, Y · g:i A') : 'Not yet published'))?></dd><dt>Expiration</dt><dd><?=e($selectedRevision['expires_at'] ? format_campus_datetime($selectedRevision['expires_at'],'M j, Y · g:i A') : 'No expiration')?></dd><dt>Event</dt><dd><?=e($selectedRevision['event_date'] ? format_campus_datetime($selectedRevision['event_date'].' 00:00:00','M j, Y').($selectedRevision['event_all_day']?' · All day':' · '.substr((string)$selectedRevision['event_start'],0,5)) : 'No event date')?></dd><dt>Deadline</dt><dd><?=e($selectedRevision['deadline_date'] ? format_campus_datetime($selectedRevision['deadline_date'].' 00:00:00','M j, Y').($selectedRevision['deadline_all_day']?' · All day':' · '.substr((string)$selectedRevision['deadline_time'],0,5)) : 'No deadline')?></dd><dt>Pinned</dt><dd><?=$selectedRevision['is_pinned']?'Yes':'No'?></dd></dl><div><?=nl2br(e($selectedRevision['caption']))?></div><?php if($selectedRevision['tags_json']): ?><p>Tags: <?=e(implode(', ', json_decode($selectedRevision['tags_json'],true) ?: []))?></p><?php endif; ?><?php if($selectedRevision['image_path']): ?><p>Image attachment: <?=e(basename($selectedRevision['image_path']))?></p><?php endif; ?><?php if($selectedRevision['video_url']): ?><p>Video URL: <?=e($selectedRevision['video_url'])?></p><?php endif; ?><form method="post" action="restore-announcement" onsubmit="return confirm('Restore this version? The current version will be kept in history.')"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$id?>"><input type="hidden" name="revision_id" value="<?=$selectedRevision['id']?>"><input type="hidden" name="version" value="<?=$announcement['version']?>"><button class="primary" type="submit">Restore this version</button></form><p><a href="announcement-history?id=<?=$id?>">Back to history</a></p></article><?php else: ?><p class="field-note"><?=$total?> saved version<?=$total===1?'':'s'?> · showing up to 50 per page.</p><?php if($revisions): ?><ol class="revision-list"><?php foreach($revisions as $revision): ?><li><div><strong>Version <?=e($revision['revision_number'])?></strong><?php if($revision['restored_from_version']): ?><span class="revision-restored">Restored from version <?=e($revision['restored_from_version'])?></span><?php endif; ?><p><?=e($revision['title'])?> · <?=e($revision['category'])?> · <?=e($revision['status'])?></p><small>Edited by <?=e($revision['editor']??'Former account')?> · <?=e(format_campus_datetime($revision['created_at'],'M j, Y · g:i A'))?></small></div><a href="announcement-history?id=<?=$id?>&amp;revision=<?=$revision['id']?>">Inspect</a></li><?php endforeach; ?></ol><?php for($pageLink=1;$pageLink<=$pages;$pageLink++): ?> <a href="announcement-history?id=<?=$id?>&amp;page=<?=$pageLink?>" <?=$pageLink===$page?'aria-current="page"':''?>><?=$pageLink?></a><?php endfor; ?><?php else: ?><div class="card"><p>No edits have been saved yet.</p></div><?php endif; ?><?php endif; ?></main></body></html>